from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI(
    openapi_extra={
        "components": {
            "securitySchemes": {
                "ApiKeyAuth": {
                    "type": "apiKey",
                    "in": "header",
                    "name": "X-API-Key",
                }
            }
        }
    }
)

@app.get("/")
def read_root():
    return {"Hello": "World"}

client = TestClient(app)

def test_openapi_security_schemes():
    response = client.get("/openapi.json")
    assert response.status_code == 200
    data = response.json()
    assert "components" in data
    assert "securitySchemes" in data["components"]
    assert "ApiKeyAuth" in data["components"]["securitySchemes"]
    print("Security schemes found in OpenAPI schema!")

if __name__ == "__main__":
    try:
        test_openapi_security_schemes()
    except AssertionError as e:
        print(f"Assertion failed: {e}")
        import sys
        sys.exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        import sys
        sys.exit(1)

